<script>
  // Whole-network schematic, generated by scripts/schematic.mjs from OSM + GTFS geography
  // (own layout, not traced from the FDTJ artwork). This component only draws it and animates vehicles.
  import { untrack } from 'svelte'
  import { sel, select, net, drawnStop, lineData, tjHead, focusIds } from './lib/state.svelte.js'
  import { trainsNow, jakartaNow } from './lib/time.js'
  import { locateOnLine, nearestStop, project } from './lib/geo.js'
  import { LANDMARKS, DISTRICTS, PERSON } from './lib/network.js'

  /** @type {{ data: any, sch: any }} */
  let { data, sch } = $props()

  const byId = new Map(sch.nodes.map((n) => [n.id, n]))
  const B = sch.bounds
  const MRT_LINE = sch.lines.find((l) => l.id === 'M')
  const OTHER = sch.lines.filter((l) => l.mode !== 'mrt')
  const RAIL = OTHER.filter((l) => l.mode !== 'tj'), BRT = OTHER.filter((l) => l.mode === 'tj')
  const TRACK = MRT_LINE.d
  const LEG_H = 300
  // The printed "sheet": every drawn thing lives inside it; the legend sits under the network.
  const SHEET = { x: B.x - 160, y: B.y - 220, w: B.w + 320, h: B.h + 360 + LEG_H }
  const FULL = { x: SHEET.x - 30, y: SHEET.y - 30, w: SHEET.w + 60, h: SHEET.h + 60 }
  const GRID = 160
  const COLS = Array.from({ length: Math.ceil(SHEET.w / GRID) }, (_, i) => SHEET.x + i * GRID)
  const ROWS = Array.from({ length: Math.ceil((SHEET.h - 80) / GRID) }, (_, i) => SHEET.y + 80 + i * GRID)
  const box = (ns, px, py) => {
    const xs = ns.map((n) => n.x), ys = ns.map((n) => n.y)
    return { x: Math.min(...xs) - px, y: Math.min(...ys) - py, w: Math.max(...xs) - Math.min(...xs) + 2 * px, h: Math.max(...ys) - Math.min(...ys) + 2 * py }
  }
  const mrtNodes = sch.nodes.filter((n) => n.mode === 'mrt')
  const MRT = box(mrtNodes, 160, 80) // phone: open on the MRT line
  const CORE = box(mrtNodes, 520, 220) // desktop: the city centre
  const lineName = Object.fromEntries(sch.lines.map((l) => [l.id, l.mode === 'tj' ? `Koridor ${l.id}` : l.name]))
  const lineColor = Object.fromEntries(sch.lines.map((l) => [l.id, l.color]))
  const hub = (n) => n.lines.length > 1
  // Line badges just past both ends of each line's main pattern.
  // A pattern that ends where it starts (TJ out-and-back, KRL loop) gets one badge, not two stacked.
  // ponytail: no badge at a round trip's far terminal; place it by matching the line name's "A – B" if wanted.
  // Badges of different lines sharing a terminus are laid side by side across the line.
  const badges = []
  for (const l of OTHER) {
    const q = l.stops[0]
    const ends = q[0] === q.at(-1) ? [[q[0], q[1]]] : [[q[0], q[1]], [q.at(-1), q.at(-2)]]
    for (const [a, b] of ends) {
      const p = byId.get(a), o = byId.get(b), d = Math.hypot(p.x - o.x, p.y - o.y) || 1
      const ux = (p.x - o.x) / d, uy = (p.y - o.y) / d
      let x = p.x + ux * 22, y = p.y + uy * 22
      for (let n = 1; badges.some((c) => Math.hypot(c.x - x, c.y - y) < 24) && n < 6; n++) {
        const side = n % 2 ? 1 : -1, step = Math.ceil(n / 2) * 26 * side
        x = p.x + ux * 22 - uy * step; y = p.y + uy * 22 + ux * step
      }
      badges.push({ l, x, y })
    }
  }
  const landmarks = LANDMARKS.map((l) => ({ ...l, ...project(l) }))
  const districts = DISTRICTS.map(([name, lat, lon]) => ({ name, ...project({ lat, lon }) }))

  let stations = $derived(
    data.stations.map((s) => {
      const n = byId.get(`mrt:${s.code}`)
      const terminus = s.code === data.line.termini.south || s.code === data.line.termini.north
      return { s, n, x: n.x, y: n.y, terminus }
    }),
  )

  let svg
  const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches

  // --- live trains: timetable position → point on the drawn MRT track ---
  let meas // hidden copy of TRACK used only for length maths
  let trains = $state([])
  // KRL / LRT / Transjakarta: no open per-trip timetable (BRT runs on headways), so vehicles are
  // simulated from typical headways (minutes) at a fixed speed (schematic units per minute).
  // ponytail: frequency simulation, not real positions; swap in GTFS/GTFS-rt if operators publish one.
  const HEAD = { A: 30, C: 10, R: 15, B: 6, T: 15, TP: 20, S: 10, BK: 10, CB: 10 }
  // Vehicles run on each line's main pattern only (branches/short-turns would multiply the fleet).
  const SEGS = OTHER.flatMap((ln) => ln.d.split(/(?=M)/).slice(0, 1).map((d, i) => ({
    key: `${ln.mode}:${ln.id}:${i}`, ln, d, color: ln.color, bus: ln.mode === 'tj', mode: ln.mode,
    head: ln.mode === 'tj' ? 9 : HEAD[ln.id] ?? 15, v: ln.mode === 'tj' ? 22 : 35, stops: ln.stops[i] ?? [],
  })))
  let rail = $state([])
  function railNow() {
    const tm = Date.now() / 60000, hour = (tm / 60 + 7) % 24
    const night = hour < 4.5 // rail stops overnight (WIB)
    return SEGS.flatMap(({ key, ln, color, bus, mode, head, v }, i) => {
      if (night && !bus) return []
      if (bus) head = tjHead(ln.id) ?? (net.tjHeadway ? 0 : head) // GTFS: null hour = no service
      if (!head) return []
      // ponytail: buses drawn at most every 4 min so the corridors stay readable; the panel shows the real interval
      const { total, at } = segPts(i), s = Math.max(bus ? 4 : 2, head) * v, out = []
      for (const dir of [1, -1]) {
        const base = tm * v + (dir < 0 ? s / 2 : 0)
        for (let j = Math.floor(base / s); base - j * s < total; j--) {
          const l = dir > 0 ? base - j * s : total - (base - j * s)
          const p = at(l), a = at(Math.max(0, l - 1)), b = at(Math.min(total, l + 1))
          out.push({ id: `${key}|${dir}|${j}`, seg: i, dir, l, mode, color, bus, x: p.x, y: p.y,
            a: (Math.atan2(b.y - a.y, b.x - a.x) * 180) / Math.PI + (dir < 0 ? 180 : 0) })
        }
      }
      return out
    })
  }
  // Points along a path string (M/L/Q only, as the generator writes it), ~step units apart, computed
  // from the numbers. brk[k] = piece index of sample k. SVG getPointAtLength is O(path) per call and
  // froze phones for seconds on the long TJ corridors.
  function pathPts(d, step) {
    const pts = [], brk = []
    let piece = -1, x = 0, y = 0
    const add = (px, py) => (pts.push([+px.toFixed(1), +py.toFixed(1)]), brk.push(piece))
    for (const [, c, args] of d.matchAll(/([MLQ])([^MLQ]*)/g)) {
      const v = args.trim().split(/[\s,]+/).map(Number)
      if (c === 'M') { piece++; x = v[0]; y = v[1]; add(x, y); continue }
      const [ex, ey] = c === 'L' ? v : v.slice(2)
      const n = Math.max(1, Math.ceil(Math.hypot(ex - x, ey - y) / step))
      for (let k = 1; k <= n; k++) {
        const t = k / n
        if (c === 'L') add(x + (ex - x) * t, y + (ey - y) * t)
        else add((1 - t) ** 2 * x + 2 * (1 - t) * t * v[0] + t * t * ex, (1 - t) ** 2 * y + 2 * (1 - t) * t * v[1] + t * t * ey)
      }
      x = ex; y = ey
    }
    return { pts, brk }
  }
  // Vehicle segments: point at length l along the path, via cumulative lengths + binary search.
  const segCache = new Map()
  function segPts(i) {
    if (!segCache.has(i)) {
      const { pts } = pathPts(SEGS[i].d, 1), cum = [0]
      for (let k = 1; k < pts.length; k++) cum.push(cum[k - 1] + Math.hypot(pts[k][0] - pts[k - 1][0], pts[k][1] - pts[k - 1][1]))
      const at = (l) => {
        let lo = 0, hi = cum.length - 1
        while (lo < hi) { const m = (lo + hi) >> 1; cum[m] < l ? (lo = m + 1) : (hi = m) }
        return { x: pts[lo][0], y: pts[lo][1] }
      }
      segCache.set(i, { total: cum.at(-1), at })
    }
    return segCache.get(i)
  }
  let track = $state(null) // {at: station code → length along TRACK, total}
  // Vehicle visibility per mode; remembered per browser (convenience only).
  const VEH = [['mrt', 'MRT'], ['krl', 'KRL & KA Bandara'], ['lrt', 'LRT'], ['tj', 'Bus Transjakarta']]
  let show = $state({ mrt: true, krl: true, lrt: true, tj: true, lm: true }) // lm = landmarks
  try { Object.assign(show, JSON.parse(localStorage.getItem('peron:veh')) ?? {}) } catch {}
  $effect(() => { try { localStorage.setItem('peron:veh', JSON.stringify(show)) } catch {} })
  const allShown = $derived(VEH.every(([m]) => show[m]))
  const dim = (m) => sel.mode !== null && sel.mode !== m // mode focus (issue #3)
  // Line focus: tapping a line dims everything that isn't on it.
  // A found route dims every line (focusLine = empty set) and redraws only the ridden stretches on top.
  const routeStops = $derived.by(() => {
    const r = sel.line ? null : sel.route?.result
    return r ? new Set(r.legs.flatMap((l) => (l.type === 'ride' ? l.stops : [l.from, l.to]))) : null
  })
  const focusLine = $derived(sel.line ? new Set(focusIds()) : routeStops ? new Set() : null) // follows the open line panel or found route
  const offL = (id) => focusLine !== null && !focusLine.has(id)
  const onFocus = (n) => (routeStops ? routeStops.has(n.id) : n.lines.some((l) => focusLine.has(l)))
  // Ridden stretch of a drawn line, hop by hop: for each pair of consecutive stops take the shortest
  // unbroken run of path samples joining them (lines can have several pieces and pass a spot twice).
  const samples = new Map()
  const sampled = (i) => samples.get(i) ?? (samples.set(i, pathPts(sch.lines[i].d, 2)), samples.get(i))
  function hop({ pts, brk }, a, b) {
    const d2 = (p, n) => (p[0] - n.x) ** 2 + (p[1] - n.y) ** 2
    // candidate samples: local minima of distance to the stop that are close to it
    const near = (n) => {
      const d = pts.map((p) => d2(p, n)), r = Math.max(196, Math.min(...d) * 1.5)
      return d.flatMap((v, k) => (v <= r && (k === 0 || v <= d[k - 1]) && (k === d.length - 1 || v <= d[k + 1]) ? [k] : []))
    }
    let best = null
    for (const i of near(a)) for (const j of near(b)) {
      const [s, e] = i < j ? [i, j] : [j, i]
      if (brk[s] === brk[e] && (!best || e - s < best[1] - best[0])) best = [s, e]
    }
    if (!best) return `M${a.x},${a.y}L${b.x},${b.y}`
    const run = pts.slice(best[0], best[1] + 1)
    if (d2(run[0], a) > d2(run.at(-1), a)) run.reverse()
    return `M${a.x},${a.y}L` + run.join('L') + `L${b.x},${b.y}` // meet the stop centres: no gaps between hops
  }
  const routeD = $derived.by(() => {
    if (!routeStops) return []
    return sel.route.result.legs.map((l) => {
      const a = byId.get(l.from), b = byId.get(l.to)
      if (l.type === 'walk') return { walk: true, d: `M${a.x},${a.y}L${b.x},${b.y}` }
      const i = sch.lines.findIndex((x) => x.id === l.line), pts = sampled(i)
      return { d: l.stops.slice(1).map((id, k) => hop(pts, byId.get(l.stops[k]), byId.get(id))).join(''), color: sch.lines[i].color }
    })
  })
  $effect(() => {
    if (!meas) return
    // track length at each station = nearest sampled point on the path
    const total = meas.getTotalLength(), pts = []
    for (let l = 0; l <= total; l += 2) pts.push([l, meas.getPointAtLength(l)])
    const at = Object.fromEntries(stations.map(({ s, x, y }) => {
      let best = pts[0]
      for (const p of pts) if (Math.hypot(p[1].x - x, p[1].y - y) < Math.hypot(best[1].x - x, best[1].y - y)) best = p
      return [s.code, best[0]]
    }))
    track = { at, total }
    let ticked = false
    const tick = () => {
      if (g.k !== 1 || g.x || g.y) return // mid-gesture: don't repaint the SVG
      const prev = new Set(trains.map((t) => t.id))
      trains = trainsNow(data.stations).map(({ dir, from, to, f, eta }) => {
        const l = at[from] + (at[to] - at[from]) * f
        const p = meas.getPointAtLength(l), q = meas.getPointAtLength(Math.min(total, l + 1))
        // a new id = the train just left `from` (ids change once per hop)
        const dep = ticked && !reduced && !prev.has(dir + from)
        if (dep) depart(from)
        // sprites face +x, so trains running against the path direction turn around
        return { id: dir + from, dir, to, eta, dep, x: p.x, y: p.y, a: (Math.atan2(q.y - p.y, q.x - p.x) * 180) / Math.PI + (dir === 'toBHI' ? 0 : 180) }
      })
      ticked = true
      rail = railNow()
    }
    untrack(tick) // tick reads + writes trains; keep it out of this effect's deps
    const t = setInterval(tick, 2000)
    return () => clearInterval(t)
  })
  // Departure ripple at the station a train just left.
  let departs = $state([])
  let dn = 0
  function depart(code) {
    const st = stations.find((x) => x.s.code === code)
    const d = { id: ++dn, x: st.x, y: st.y }
    departs.push(d)
    setTimeout(() => (departs = departs.filter((x) => x.id !== d.id)), 1800)
  }
  // Landmark sprites are pre-rendered PNGs (see landmarks.html); three.js never ships to visitors.
  const sprite = (model) => `${import.meta.env.BASE_URL}landmarks/${model}.png`
  let vb = $state({ ...(matchMedia('(min-width: 768px)').matches ? CORE : MRT) })
  // Level of detail: halte names only once zoomed in enough to read them.
  let far = $derived(vb.w > 1500)

  // --- pan / pinch / wheel zoom ---
  // During a gesture we only move a CSS transform on the <svg> (GPU-composited, no SVG re-render),
  // then commit once to the viewBox when the gesture ends. Re-rendering ~500 nodes per pointermove lagged on Safari.
  const pointers = new Map()
  let moved = false
  let g = { x: 0, y: 0, k: 1 } // live px transform
  let wheelT
  // viewBox → screen mapping for preserveAspectRatio="xMidYMid meet" (.wrap sits at 0,0)
  function fit() {
    const W = svg.clientWidth, H = svg.clientHeight, s = Math.min(W / vb.w, H / vb.h)
    return { s, ox: (W - vb.w * s) / 2, oy: (H - vb.h * s) / 2 }
  }
  const scale = () => fit().s // px per unit
  function toUnits(cx, cy) {
    const { s, ox, oy } = fit()
    return [vb.x + (cx - ox) / s, vb.y + (cy - oy) / s]
  }
  const paint = () => (svg.style.transform = `translate(${g.x}px,${g.y}px) scale(${g.k})`)
  function zoomAt(cx, cy, f) {
    const k = Math.min(vb.w / 120, Math.max(vb.w / (FULL.w * 1.3), g.k * f))
    f = k / g.k
    g = { x: (g.x - cx) * f + cx, y: (g.y - cy) * f + cy, k }
    paint()
  }
  function commit() {
    const { x, y, k } = g
    if (k === 1 && !x && !y) return
    const { s, ox, oy } = fit()
    vb = { x: vb.x + (ox - x - ox * k) / (k * s), y: vb.y + (oy - y - oy * k) / (k * s), w: vb.w / k, h: vb.h / k }
    g = { x: 0, y: 0, k: 1 }
    svg.style.transform = ''
  }
  function down(e) {
    pointers.set(e.pointerId, [e.clientX, e.clientY])
    if (pointers.size === 1) moved = false
  }
  function move(e) {
    const prev = pointers.get(e.pointerId)
    if (!prev) return
    if (pointers.size === 1) {
      const dx = e.clientX - prev[0], dy = e.clientY - prev[1]
      if (Math.abs(dx) + Math.abs(dy) > 2) moved = true
      g = { ...g, x: g.x + dx, y: g.y + dy }
      paint()
    } else if (pointers.size === 2) {
      const other = [...pointers.values()].find((p) => p !== prev)
      const d0 = Math.hypot(prev[0] - other[0], prev[1] - other[1])
      const d1 = Math.hypot(e.clientX - other[0], e.clientY - other[1])
      moved = true
      if (d0 > 0) zoomAt((e.clientX + other[0]) / 2, (e.clientY + other[1]) / 2, d1 / d0)
    }
    pointers.set(e.pointerId, [e.clientX, e.clientY])
  }
  function up(e) {
    if (pointers.delete(e.pointerId) && !pointers.size) commit()
  }
  function wheel(e) {
    e.preventDefault()
    zoomAt(e.clientX, e.clientY, Math.exp(-e.deltaY * 0.0015))
    clearTimeout(wheelT)
    wheelT = setTimeout(commit, 150)
  }
  function zoomBtn(f) {
    zoomAt(svg.clientWidth / 2, svg.clientHeight / 2, f)
    commit()
  }

  // --- tap feedback: ripple at the point, bounce the shape, info bubble for points without a panel ---
  let burst = $state(null) // {x, y, k}
  let info = $state(null) // {x, y, title, sub, code?}
  let nk = 0
  function tap(e, x, y, bubble) {
    e.stopPropagation()
    if (moved) return
    burst = { x, y, k: ++nk }
    // Stops with a detail panel open it straight away, like MRT stations; the rest get a bubble.
    if (bubble?.stop) (select(null), (sel.stop = bubble.stop), (bubble = null))
    else if (bubble?.rows) (select(null), (sel.stop = null), (sel.line = bubble), (bubble = null))
    else sel.line = null
    info = bubble ? { x, y, k: nk, ...bubble } : null
    if (!reduced)
      e.currentTarget.querySelector('.bounce')?.animate(
        [{ transform: 'scale(1)' }, { transform: 'scale(1.35)' }, { transform: 'scale(0.92)' }, { transform: 'scale(1)' }],
        { duration: 450, easing: 'ease-out' },
      )
  }
  // --- vehicle info (tap a train/bus sprite) ---
  const hhmm = (m) => `${String(Math.floor(m / 60) % 24).padStart(2, '0')}:${String(Math.floor(m % 60)).padStart(2, '0')}`
  function mrtInfo(tr) {
    const next = data.stations.find((s) => s.code === tr.to)
    return { title: `MRT → ${tr.dir === 'toBHI' ? 'Bundaran HI' : 'Lebak Bulus'}`, sub: `Berikutnya: ${next.name} · tiba ±${hhmm(tr.eta)}` }
  }
  // Stops of a segment, as lengths along its drawn path (sampled once, on first tap).
  const along = new Map()
  function stopsAlong(i) {
    if (along.has(i)) return along.get(i)
    const { total, at } = segPts(i), pts = []
    for (let l = 0; l <= total; l += 2) pts.push([l, at(l)])
    const out = SEGS[i].stops.map((id) => {
      const c = byId.get(id)
      return { name: c.name, l: pts.reduce((a, b) => (Math.hypot(b[1].x - c.x, b[1].y - c.y) < Math.hypot(a[1].x - c.x, a[1].y - c.y) ? b : a))[0] }
    })
    along.set(i, out.sort((a, b) => a.l - b.l))
    return along.get(i)
  }
  function vehInfo(tr) {
    const { ln, bus } = SEGS[tr.seg], st = stopsAlong(tr.seg)
    const dest = (tr.dir > 0 ? st.at(-1) : st[0])?.name ?? ln.name
    const next = tr.dir > 0 ? st.find((s) => s.l > tr.l + 3) : st.findLast((s) => s.l < tr.l - 3)
    return {
      title: `${bus ? `TJ ${ln.id}` : ln.name} → ${dest}`,
      sub: `${next ? `Berikutnya: ${next.name} · ` : ''}${bus && tjHead(ln.id) ? `tiap ±${Math.round(tjHead(ln.id))} mnt · ` : ''}posisi simulasi`,
    }
  }
  // Vehicles running on a line right now (MRT from the timetable, the rest simulated).
  const fleet = (id) => (id === 'M' ? trains.length : rail.filter((t) => SEGS[t.seg].ln.id === id).length)
  // Every line drawn through the tapped point (shared track/corridor), not just the topmost one.
  function lineInfo(e, x, y) {
    const pt = new DOMPoint(x, y)
    const here = sch.lines.filter((ln, i) => !dim(ln.mode) && hitEls[i]?.isPointInStroke(pt))
    if (!here.length) here.push(sch.lines.find((l) => l.d === e.currentTarget.getAttribute('d')))
    return lineData(here.map((l) => l.id), fleet)
  }
  const hitEls = []
  // Click point in schematic units (getScreenCTM includes the pan/zoom CSS transform).
  function svgPt(e) {
    const m = e.currentTarget.getScreenCTM().inverse()
    return [e.clientX * m.a + e.clientY * m.c + m.e, e.clientX * m.b + e.clientY * m.d + m.f]
  }
  const keyTap = (fn) => (e) => (e.key === 'Enter' || e.key === ' ') && (e.preventDefault(), fn(e))
  const lines = (n) => n.lines.map((id) => lineName[id]).join(', ')
  function landmarkInfo(lm) {
    const mrt = data.stations.find((x) => x.code === lm.near)
    if (mrt) return { title: lm.name, sub: `Stasiun terdekat: ${mrt.name} (MRT)`, code: mrt.code }
    const n = sch.nodes.find((x) => x.name === lm.near)
    return { title: lm.name, sub: n ? `Terdekat: ${n.name} (${lines(n)})` : `Akses: ${lm.near}` }
  }
  // The real stop (net.stops item) a schematic node stands for → its detail panel.
  const realStop = (n) => net.stops.find((s) => s.mode === n.mode && s.name === n.name)
  const KIND = { krl: 'Stasiun KRL', lrt: 'Stasiun LRT', tj: 'Halte Transjakarta' }
  const nodeInfo = (n) => ({ stop: realStop(n), title: n.name, sub: `${KIND[n.mode]} · ${lines(n)}` })

  function pick(code) {
    if (!moved) select(code)
  }
  function key(e, code) {
    if (e.key === 'Enter' || e.key === ' ') (e.preventDefault(), select(code))
  }

  // Desktop: shift the initial fit right so the search button/panels don't cover the centre.
  $effect(() => {
    if (svg && matchMedia('(min-width: 768px)').matches) untrack(() => (vb = { ...vb, x: vb.x - 330 / scale() / 2 }))
  })

  // Pan so schematic point (x, y) sits beside / above the panel.
  function centreOn(x, y) {
    const desktop = matchMedia('(min-width: 768px)').matches
    const tx = desktop ? 390 + (innerWidth - 390) / 2 : innerWidth / 2
    const ty = desktop ? innerHeight / 2 : innerHeight * 0.21
    const [ux, uy] = toUnits(tx, ty)
    vb = { ...vb, x: vb.x + x - ux, y: vb.y + y - uy }
  }
  // Keep the selected station / stop visible.
  $effect(() => {
    const st = stations.find((x) => x.s.code === sel.station)
    if (st && svg) untrack(() => centreOn(st.x, st.y))
  })
  $effect(() => {
    const n = sel.stop && drawnStop(sel.stop)
    if (n && svg) untrack(() => centreOn(n.x, n.y))
  })

  // A stop picked in search: pan to it and ripple.
  // ponytail: "fresh" = picked < 3 s ago, so remounting the view doesn't re-pan to an old pick.
  $effect(() => {
    const f = sel.focus
    if (!f || Date.now() - f.k > 3000 || !svg) return
    untrack(() => {
      const a = drawnStop(f)
      if (!a) return
      centreOn(a.x, a.y)
      burst = { x: a.x, y: a.y, k: ++nk }
    })
  })
  // GPS (issue #2). Nearest non-MRT stop → its node; MRT → interpolate along the MRT track.
  let me = $derived.by(() => {
    if (!sel.me || !track) return null
    const near = nearestStop(data.stations, net.stops, sel.me)
    const a = near.mode !== 'mrt' && drawnStop(near)
    if (a) return { x: a.x, y: a.y, far: near.dist > 1500 }
    const loc = locateOnLine(data.stations, sel.me)
    const p = meas.getPointAtLength(track.at[loc.from] + (track.at[loc.to] - track.at[loc.from]) * loc.t)
    return { x: p.x, y: p.y, far: loc.off > 1500 }
  })
  let centred = false
  $effect(() => {
    if (!me) return void (centred = false)
    if (!centred) (centred = true), untrack(() => centreOn(me.x, me.y))
  })
</script>

<!-- Top-down vehicle sprites, front facing +x. Trains: rounded nose, cab glass, car joints. Bus: boxy, windscreen, roof AC, mirrors. -->
{#snippet vehicle(kind, color)}
  {#if kind === 'bus'}
    <rect class="body" x="-7" y="-3.8" width="14" height="7.6" rx="1.8" style:fill={color} />
    <rect class="glass" x="4.3" y="-2.9" width="1.9" height="5.8" rx="0.6" />
    <rect class="roof" x="-4" y="-2" width="5.5" height="4" rx="0.8" />
    <path class="mirror" d="M6,-3.8 l1.4,-1 M6,3.8 l1.4,1" />
  {:else}
    {@const h = kind === 'lrt' ? 16 : kind === 'krl' ? 26 : 24}
    {@const n = Math.round(h / 8)}
    <path class="body" d="M{-h / 2},-3.8 H{h / 2 - 4} Q{h / 2},-3.8 {h / 2},0 Q{h / 2},3.8 {h / 2 - 4},3.8 H{-h / 2} Z" style:fill={color} />
    <path class="glass" d="M{h / 2 - 3.4},-2.6 Q{h / 2 - 0.9},-2.1 {h / 2 - 0.9},0 Q{h / 2 - 0.9},2.1 {h / 2 - 3.4},2.6 Z" />
    {#each { length: n - 1 }, i}<line class="joint" x1={-h / 2 + ((i + 1) * h) / n} y1="-3.8" x2={-h / 2 + ((i + 1) * h) / n} y2="3.8" />{/each}
  {/if}
{/snippet}

<svelte:window onpointermove={move} onpointerup={up} onpointercancel={up} onkeydown={(e) => e.key === 'Escape' && ((info = null), (sel.line = null))} />

<div class="wrap">
  <!-- svelte-ignore a11y_click_events_have_key_events, a11y_no_noninteractive_element_interactions (background tap closes the bubble; Escape is the keyboard path) -->
  <svg
    bind:this={svg}
    class:far
    viewBox="{vb.x} {vb.y} {vb.w} {vb.h}"
    role="img"
    aria-label="Peta skematik transportasi umum Jakarta"
    onpointerdown={down}
    onclick={() => !moved && ((info = null), (sel.line = null))}
    onwheel={wheel}
  >
    <defs>
      <clipPath id="sheet-clip"><rect x={SHEET.x} y={SHEET.y} width={SHEET.w} height={SHEET.h} rx="22" /></clipPath>
      <pattern id="hatch" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="6" height="6" fill="#efede8" /><rect width="2.4" height="6" fill="#d9d5cc" /></pattern>
    </defs>

    <!-- flat offset shadow: an SVG blur filter re-rasterizes on every frame in Safari -->
    <rect x={SHEET.x} y={SHEET.y + 8} width={SHEET.w} height={SHEET.h} rx="22" class="sheet-shadow" />
    <rect x={SHEET.x} y={SHEET.y} width={SHEET.w} height={SHEET.h} rx="22" class="sheet" />
    <g clip-path="url(#sheet-clip)">
      <g class="grid">
        {#each COLS.slice(1) as x}<line x1={x} x2={x} y1={SHEET.y + 80} y2={SHEET.y + SHEET.h} />{/each}
        {#each ROWS.slice(1) as y}<line y1={y} y2={y} x1={SHEET.x} x2={SHEET.x + SHEET.w} />{/each}
      </g>
      {#each COLS as x, i}<text class="ref" x={x + GRID / 2} y={SHEET.y + 104}>{i + 1}</text>{/each}
      {#each ROWS as y, i}<text class="ref" x={SHEET.x + 16} y={y + GRID / 2 + 4}>{String.fromCharCode(65 + i)}</text>{/each}

      <rect x={SHEET.x} y={SHEET.y} width={SHEET.w} height="80" class="band" />
      <rect x={SHEET.x} y={SHEET.y + 80} width={SHEET.w} height="5" style:fill={data.line.color} />
      <text class="title" x={SHEET.x + 34} y={SHEET.y + 46}>Peta Integrasi Transportasi Jakarta</text>
      <text class="subtitle" x={SHEET.x + 34} y={SHEET.y + 68}>MRT · KRL · KA Bandara · LRT · Transjakarta Koridor 1–14</text>
      <text class="subtitle" x={SHEET.x + SHEET.w - 34} y={SHEET.y + 46} text-anchor="end">Skema, tidak berskala</text>
    </g>

    {#each districts as d}<text class="district" x={d.x} y={d.y}>{d.name}</text>{/each}
    <g class="compass" transform="translate({SHEET.x + SHEET.w - 70},{SHEET.y + 150})" aria-hidden="true">
      <circle r="22" />
      <path d="M0,-17 L6,2 L0,-2 L-6,2 Z" class="needle" />
      <path d="M0,17 L6,2 L0,6 L-6,2 Z" />
      <text y="-27">U</text>
    </g>

    <!-- transfers: ≤150 m = same-complex connector (black bar); farther = walking zone (hatched) -->
    {#each sch.links as [x1, y1, x2, y2, m]}
      <g class="link" class:dim={sel.mode !== null || focusLine !== null}>
        {#if m > 150}<line {x1} {y1} {x2} {y2} class="walk-edge" /><line {x1} {y1} {x2} {y2} stroke="url(#hatch)" class="walk-fill" />
        {:else}<line {x1} {y1} {x2} {y2} class="conn-edge" /><line {x1} {y1} {x2} {y2} class="conn" />{/if}
      </g>
    {/each}

    <!-- Transjakarta: thin, under the rail lines -->
    {#each BRT as c (c.id)}
      <path d={c.d} class="brt-casing" class:dim={dim('tj') || offL(c.id)} pathLength="1" />
      <path d={c.d} class="brt" class:dim={dim('tj') || offL(c.id)} pathLength="1" style:stroke={c.color} />
    {/each}
    {#each RAIL as ln (ln.id)}
      <path d={ln.d} class="casing thin" class:dim={dim(ln.mode) || offL(ln.id)} pathLength="1" />
      <path d={ln.d} class="line" class:dim={dim(ln.mode) || offL(ln.id)} pathLength="1" style:stroke={ln.color} />
    {/each}
    <path d={TRACK} class="casing" class:dim={dim('mrt') || offL('M')} pathLength="1" />
    <path d={TRACK} class="track" class:dim={dim('mrt') || offL('M')} pathLength="1" style:stroke={data.line.color} />
    <!-- wide invisible hit areas: tap a line → what it is, and focus it -->
    {#each sch.lines as ln, i (ln.id)}
      {@const go = (e) => { const [x, y] = svgPt(e); tap(e, x, y, lineInfo(e, x, y)) }}
      <path bind:this={hitEls[i]} d={ln.d} class="lhit" class:off={dim(ln.mode)} role="button" tabindex="-1" aria-label={lineName[ln.id]} onclick={go} onkeydown={keyTap(go)} />
    {/each}
    {#each routeD as r, i (i)}
      {#if r.walk}<path d={r.d} class="rwalk" />
      {:else}<path d={r.d} class="rcase" /><path d={r.d} class="rline" style:stroke={r.color} />{/if}
    {/each}

    {#each badges as b}
      <g class="badge" class:dim={dim(b.l.mode) || offL(b.l.id)} transform="translate({b.x},{b.y})">
        {#if b.l.mode === 'tj'}
          <rect x={b.l.id.length > 1 ? -13 : -10} y="-8" width={b.l.id.length > 1 ? 26 : 20} height="16" rx="4" style:fill={b.l.color} />
        {:else}
          <circle r="11" style:fill={b.l.color} />
        {/if}
        <text y="4">{b.l.id}</text>
      </g>
    {/each}

    <!-- landmarks sit above the lines (lines never cut through a sprite), under the stops -->
    {#each show.lm ? landmarks : [] as lm, i}
      {@const go = (e) => tap(e, lm.x, lm.y - lm.s * 0.2, landmarkInfo(lm))}
      <g class="tap" class:dim={focusLine !== null} role="button" tabindex="0" aria-label={lm.name} onclick={go} onkeydown={keyTap(go)}>
        <image class="lm bounce" style:animation-delay="{i * 60}ms" href={sprite(lm.model)} x={lm.x - lm.s / 2} y={lm.y - lm.s / 2} width={lm.s} height={lm.s} />
        <text class="lmname" x={lm.x} y={lm.y + lm.s / 2 + 4}>{lm.name}</text>
      </g>
    {/each}

    {#each sch.nodes as n (n.id)}
      {#if n.mode !== 'mrt'}
        {@const go = (e) => tap(e, n.x, n.y, nodeInfo(n))}
        {@const tj = n.mode === 'tj'}
        <g class="tap {tj ? 'htj' : 'other'}" class:hubn={hub(n)} class:dim={dim(n.mode) || (focusLine !== null && !onFocus(n))} role="button" tabindex="-1" aria-label="{tj ? 'Halte' : 'Stasiun'} {n.name}" onclick={go} onkeydown={keyTap(go)}>
          <circle cx={n.x} cy={n.y} r="11" class="hit" />
          {#if tj}
            <circle cx={n.x} cy={n.y} r={hub(n) ? 4.6 : 3.4} class="bounce {hub(n) ? 'hub' : 'halte'}" style:stroke={hub(n) ? null : lineColor[n.lines[0]]} />
          {:else}
            <circle cx={n.x} cy={n.y} r={hub(n) ? 7 : 5} class="ring rst bounce" />
          {/if}
          <text x={n.lx} y={n.ly} text-anchor={n.la} transform={n.rot ? `rotate(${n.rot} ${n.lx} ${n.ly})` : null} class={tj ? 'hname' : 'oname'} class:strong={hub(n)} style:font-size="{n.fs}px">{n.name}</text>
        </g>
      {/if}
    {/each}

    <path d={TRACK} class="meas" bind:this={meas} />
    {#each rail.filter((t) => show[t.mode]) as tr (tr.id)}
      {@const go = (e) => tap(e, tr.x, tr.y, vehInfo(tr))}
      <g class="train rail tap" class:still={reduced} class:dim={dim(tr.mode) || offL(SEGS[tr.seg].ln.id)} style:transform="translate({tr.x}px,{tr.y}px) rotate({tr.a}deg)" role="button" tabindex="-1" aria-label={tr.bus ? 'Bus Transjakarta' : 'Kereta'} onclick={go} onkeydown={keyTap(go)}>
        <circle r="11" class="hit" />
        {@render vehicle(tr.bus ? 'bus' : tr.mode, tr.color)}
      </g>
    {/each}
    {#each show.mrt ? trains : [] as tr (tr.id)}
      {@const go = (e) => tap(e, tr.x, tr.y, mrtInfo(tr))}
      <g class="train tap" class:still={reduced} class:dep={tr.dep} class:dim={dim('mrt') || offL('M')} style:transform="translate({tr.x}px,{tr.y}px) rotate({tr.a}deg)" role="button" tabindex="-1" aria-label="Kereta MRT" onclick={go} onkeydown={keyTap(go)}>
        <circle r="13" class="hit" />
        {#if tr.dep}<rect class="trail" x="-38" y="-2.5" width="24" height="5" rx="2.5" />{/if}
        {@render vehicle('mrt', 'var(--navy)')}
      </g>
    {/each}

    {#each stations as { s, n, x, y, terminus } (s.code)}
      {@const on = sel.station === s.code}
      <g
        class="st"
        class:on
        class:dim={dim('mrt') || (routeStops ? !routeStops.has(n.id) : offL('M'))}
        role="button"
        tabindex="0"
        aria-label="Stasiun {s.name}"
        aria-pressed={on}
        onclick={(e) => (tap(e, x, y), pick(s.code))}
        onkeydown={(e) => key(e, s.code)}
      >
        <circle cx={x} cy={y} r="22" class="hit" />
        {#if on}<circle cx={x} cy={y} r="16" class="pulse" /><circle cx={x} cy={y} r="16" class="halo" />{/if}
        <circle cx={x} cy={y} r={terminus ? 9 : 7.5} class="ring bounce" class:terminus style:stroke={terminus ? data.line.color : null} />
        <text x={n.lx} y={n.ly} text-anchor={n.la} transform={n.rot ? `rotate(${n.rot} ${n.lx} ${n.ly})` : null} class="name">{s.name}</text>
      </g>
    {/each}

    {#each show.mrt ? departs : [] as d (d.id)}
      <circle cx={d.x} cy={d.y} r="8" class="dep-ring" class:dim={dim('mrt')} />
    {/each}

    {#if me}
      <g class="me" class:far={me.far} transform="translate({me.x},{me.y})" role="img" aria-label="Lokasi Anda (perkiraan)">
        <ellipse rx="10" ry="3.5" class="me-halo" />
        <ellipse cy="0.5" rx="6" ry="2" class="me-shadow" />
        <g class="me-dot"><path d={PERSON.body} /><circle cy={PERSON.head.cy} r={PERSON.head.r} /></g>
      </g>
    {/if}

    <g class="legend" transform="translate({SHEET.x + 50},{SHEET.y + SHEET.h - LEG_H + 10})">
      <text class="lg-title" y="0">Legenda</text>
      <text class="lg-head" y="30">Kereta</text>
      {#each [{ name: `MRT ${data.line.name}`, color: data.line.color }, ...RAIL] as ln, i}
        <line x1="0" x2="30" y1={50 + i * 20} y2={50 + i * 20} class="lg-line" style:stroke={ln.color} />
        <text x="40" y={54 + i * 20}>{ln.name}</text>
      {/each}
      <text class="lg-head" x="300" y="30">Transjakarta</text>
      {#each BRT as c, i}
        <g transform="translate({300 + Math.floor(i / 10) * 300},{50 + (i % 10) * 20})">
          <g class="badge" transform="translate(12,0)">
            <rect x={c.id.length > 1 ? -13 : -10} y="-8" width={c.id.length > 1 ? 26 : 20} height="16" rx="4" style:fill={c.color} />
            <text y="4">{c.id}</text>
          </g>
          <text x="34" y="4">{c.name}</text>
        </g>
      {/each}
      <g transform="translate(900,30)">
        <text class="lg-head" y="0">Simbol</text>
        <circle cx="12" cy="22" r="7.5" class="ring" /><text x="34" y="26">Stasiun MRT</text>
        <circle cx="12" cy="44" r="5" class="ring rst" /><text x="34" y="48">Stasiun KRL/LRT</text>
        <circle cx="12" cy="66" r="3.4" class="halte" style:stroke="#4a5160" /><text x="34" y="70">Halte BRT</text>
        <circle cx="12" cy="88" r="4.6" class="hub" /><text x="34" y="92">Halte transit antarkoridor</text>
        <g class="link"><line x1="6" y1="110" x2="18" y2="110" class="conn-edge" /><line x1="6" y1="110" x2="18" y2="110" class="conn" /></g><text x="34" y="114">Transfer satu kompleks</text>
        <g class="link"><line x1="6" y1="132" x2="18" y2="132" class="walk-edge" /><line x1="6" y1="132" x2="18" y2="132" stroke="url(#hatch)" class="walk-fill" /></g><text x="34" y="136">Transfer jalan kaki (keluar stasiun)</text>
        <g class="train still" transform="translate(6,154)">{@render vehicle('lrt', 'var(--navy)')}</g>
        <g class="train still" transform="translate(24,154)">{@render vehicle('bus', '#1f5fbf')}</g>
        <text x="38" y="158">Kereta/bus (MRT dari jadwal · lainnya simulasi)</text>
      </g>
    </g>
    {#if burst && !reduced}{#key burst.k}<circle class="burst" cx={burst.x} cy={burst.y} r="12" />{/key}{/if}
    {#if info}
      {@const w = Math.max(info.title.length * 7.6, info.sub.length * 5.4, 110) + 26}
      {@const h = info.code ? 58 : 44}
      {@const open = (e) => (e.stopPropagation(), info.code && select(info.code), (info = null))}
      <g transform="translate({info.x},{info.y - 12})">
        {#key info.k}
          <g class="bubble" role="button" tabindex="0" aria-label="{info.title}. {info.sub}" onclick={open} onkeydown={keyTap(open)}>
            <path d="M-7,-9 L0,0 L7,-9 Z" />
            <rect x={-w / 2} y={-8 - h} width={w} height={h} rx="10" />
            <text class="b-title" y={-h + 11}>{info.title}</text>
            <text class="b-sub" y={-h + 27}>{info.sub}</text>
            {#if info.code}<text class="b-cta" y={-h + 43}>Buka stasiun ›</text>{/if}
          </g>
        {/key}
      </g>
    {/if}
    <text class="foot" x={SHEET.x + SHEET.w - 30} y={SHEET.y + SHEET.h - 22} text-anchor="end">
      Disusun Peron dari data OSM, MRT Jakarta, dan GTFS Transjakarta. Tata letak dibuat otomatis berdasarkan peta, bukan peta resmi dari pemerintah.
    </text>
  </svg>

  <div class="zoom">
    <button onclick={() => zoomBtn(1.5)} aria-label="Perbesar">
      <svg viewBox="0 0 20 20" aria-hidden="true"><path d="M10 4v12M4 10h12" /></svg>
    </button>
    <button onclick={() => zoomBtn(1 / 1.5)} aria-label="Perkecil">
      <svg viewBox="0 0 20 20" aria-hidden="true"><path d="M4 10h12" /></svg>
    </button>
    <button onclick={() => (vb = { ...FULL })} aria-label="Tampilkan seluruh peta">
      <svg viewBox="0 0 20 20" aria-hidden="true"><path d="M8 3H3v5M12 3h5v5M8 17H3v-5M12 17h5v-5" /></svg>
    </button>
  </div>

  <details class="veh">
    <summary aria-label="Tampilkan kendaraan & landmark">
      <svg viewBox="0 0 20 20" aria-hidden="true"><rect x="4" y="3" width="12" height="12" rx="3" /><path d="M4 10h12M7 18l1.5-3M13 18l-1.5-3" /><circle cx="7.5" cy="12.5" r=".6" /><circle cx="12.5" cy="12.5" r=".6" /></svg>
    </summary>
    <div class="veh-panel">
      <p>Kendaraan</p>
      <label class="all"><input type="checkbox" checked={allShown} indeterminate={!allShown && VEH.some(([m]) => show[m])} onchange={(e) => VEH.forEach(([m]) => (show[m] = e.currentTarget.checked))} /> Semua</label>
      {#each VEH as [m, label]}
        <label><input type="checkbox" bind:checked={show[m]} /> {label}</label>
      {/each}
      <p class="sep">Peta</p>
      <label><input type="checkbox" bind:checked={show.lm} /> Landmark</label>
    </div>
  </details>
</div>

<style>
  .wrap { position: fixed; inset: 0; z-index: 1; background: #e6eaf0; }
  svg {
    width: 100%; height: 100%; display: block; touch-action: none; user-select: none; cursor: grab;
    font-family: 'PT Sans Narrow', 'Arial Narrow', sans-serif;
    transform-origin: 0 0; will-change: transform;
  }
  svg:active { cursor: grabbing; }
  .sheet { fill: #fff; }
  .sheet-shadow { fill: rgb(11 31 58 / 0.07); }
  .band { fill: var(--navy); }
  .title { fill: #fff; font-size: 30px; font-weight: 700; letter-spacing: -0.01em; }
  .subtitle { fill: #c6d0e0; font-size: 15px; }
  .grid line { stroke: #e7eaef; stroke-width: 1; stroke-dasharray: 4 5; }
  .ref { fill: #9aa3b2; font-size: 13px; font-weight: 700; text-anchor: middle; }
  .lmname { fill: #4f6a3a; font-size: 11px; font-style: italic; font-weight: 700; text-anchor: middle; paint-order: stroke; stroke: #fff; stroke-width: 3px; stroke-linejoin: round; }
  /* entrance: lines draw in, then stations/labels fade up, landmarks pop */
  .line, .casing, .track, .brt, .brt-casing { animation: draw 1.1s cubic-bezier(0.3, 0.7, 0.2, 1) backwards; }
  .track, .casing:not(.thin) { animation-duration: 1.4s; }
  .brt, .brt-casing { animation-delay: 0.25s; }
  @keyframes draw { from { stroke-dasharray: 1 1; stroke-dashoffset: 1; } to { stroke-dasharray: 1 1; stroke-dashoffset: 0; } }
  .st, .other, .halte, .hub, .hname, .badge, .end, .lmname { animation: fade 0.5s 0.8s ease-out backwards; }
  @keyframes fade { from { opacity: 0; } }
  .lm { transform-box: fill-box; transform-origin: 50% 80%; animation: pop 0.6s 0.9s cubic-bezier(0.2, 0.9, 0.3, 1.35) backwards; }
  @keyframes pop { from { opacity: 0; transform: translateY(14px) scale(0.6); } }
  .meas { fill: none; stroke: none; }
  .train { transition: transform 2s linear; }
  .train.still { transition: none; }
  .train.dep { transition-timing-function: cubic-bezier(0.5, 0, 0.9, 0.6); } /* pulls away: slow start */
  .train.dep .body { animation: dep-flash 1.2s ease-out; }
  .trail { fill: var(--navy); transform-box: fill-box; transform-origin: center; animation: trail 1.6s ease-out forwards; }
  @keyframes trail { 0% { opacity: 0; transform: scaleX(0.2); } 25% { opacity: 0.45; } 100% { opacity: 0; transform: scaleX(1.2); } }
  @keyframes dep-flash { 0%, 40% { fill: #e2231a; } 100% { fill: var(--navy); } }
